import React from 'react';
import RecruiterChat from './RecruiterChat';

const RightChatPanel = ({ token }) => {
  return (
    <div style={{
      position: 'fixed',
      right: 16,
      top: 80,
      bottom: 16,
      width: 360,
      background: 'var(--card-bg, #0f172a)',
      border: '1px solid rgba(255,255,255,0.08)',
      borderRadius: 12,
      padding: 12,
      overflow: 'hidden',
      zIndex: 10,
      boxShadow: '0 8px 24px rgba(0,0,0,0.35)'
    }}>
      <div style={{ position: 'sticky', top: 0, background: 'transparent', paddingBottom: 8 }}>
        <h3 style={{ margin: 0 }}>Recruiter Chat</h3>
        <p className="muted" style={{ margin: 0 }}>Ask about the entire corpus.</p>
      </div>
      <div style={{ height: 'calc(100% - 56px)', overflow: 'auto' }}>
        <RecruiterChat token={token} />
      </div>
    </div>
  );
};

export default RightChatPanel;
